const now = new Date(msg.payload);
const weekday = ((now.getDay() + 6) % 7) + 1; // JS Sunday=0 -> ISO 8601 Monday=1..Sunday=7
msg.payload = {
    datetime: {
        year: now.getFullYear(),
        month: now.getMonth() + 1,
        day: now.getDate(),
        weekday,
        hour: now.getHours(),
        minute: now.getMinutes(),
        second: now.getSeconds()
    }
};
return msg;

if (msg.payload && msg.payload.source) {
    msg.payload = `heartbeat: ${msg.payload.source} fired`;
} else if (msg.payload && msg.payload.year !== undefined) {
    const p = msg.payload;
    msg.payload = `${p.year}-${String(p.month).padStart(2,'0')}-${String(p.day).padStart(2,'0')} ` +
        `${String(p.hour).padStart(2,'0')}:${String(p.minute).padStart(2,'0')}:${String(p.second).padStart(2,'0')}  ${p.temperature_c.toFixed(2)} C`;
}
return msg;
